81	  }
82	}
83	
84	@Injectable()
85	class CountingInterceptor implements NestInterceptor {
86	  intercept(_context: ExecutionContext, next: CallHandler): Observable<any> {
87	    counters.interceptor++;
88	    return next.handle();
89	  }
90	}
91	
92	@Controller()
93	class SideEffectController {
94	  @Get('slow')
95	  async slow(@Query('q', CountingPipe) _q?: string) {
96	    counters.handler++;
