341	  it('should reject a request whose body completes after shutdown started, without side effects', async () => {
342	    resetAppCounters();
343	
344	    app = await NestFactory.create<NestFastifyApplication>(
345	      AppModule,
346	      new FastifyAdapter({ return503OnClosing: true }),
347	      {
348	        logger: false,
349	      },
350	    );
351	    await app.listen(0);
352	    const port = app.getHttpServer().address().port;
353	
354	    const socket = net.createConnection(port, '127.0.0.1');
355	    socket.on('error', () => {});
356	    await new Promise<void>(resolve => socket.once('connect', resolve));
357	
358	    const body = JSON.stringify({ hello: 'world' });
359	    socket.write(
360	      `POST /echo HTTP/1.1\r\nHost: localhost:${port}\r\nContent-Type: application/json\r\nContent-Length: ${Buffer.byteLength(body)}\r\n\r\n`,
361	    );
