380	    expect(rawResponse.toLowerCase()).toContain('connection: close');
381	    expect(rawResponse).toContain('Service Unavailable');
382	
383	    // A follow-up request on the same connection cannot go through anymore:
384	    // the connection is closed, so it gets no response at all
385	    let extraData = '';
386	    socket.on('data', chunk => (extraData += chunk));
387	    socket.write('GET /slow HTTP/1.1\r\nHost: localhost\r\n\r\n');
388	    await new Promise(r => setTimeout(r, 150));
389	    expect(extraData).toBe('');
