401	    app = await NestFactory.create<NestFastifyApplication>(
402	      AppModule,
403	      new FastifyAdapter({ return503OnClosing: true }),
404	      {
405	        logger: false,
406	      },
407	    );
408	    await app.listen(0);
409	    const port = app.getHttpServer().address().port;
410	
411	    const requestPromise = request(port, '/error');
412	    await new Promise(r => setTimeout(r, 20));
413	
414	    const closePromise = app.close();
415	
416	    const response = await requestPromise;
417	    expect(response.status).toBe(500);
418	    expect(response.body).toContain('Internal server error');
419	
420	    await closePromise;
421	  }, 10000);
422	
423	  it('should wait for the in-flight request and run cleanup once across concurrent close() calls', async () => {
424	    resetAppCounters();
425	
426	    app = await NestFactory.create<NestFastifyApplication>(
427	      AppModule,
428	      new FastifyAdapter({ return503OnClosing: true }),
429	      {
430	        logger: false,
431	      },
432	    );
433	    await app.listen(0);
434	    const port = app.getHttpServer().address().port;
435	
436	    let requestSettled = false;
437	    const requestPromise = request(port, '/slow?delay=400').then(response => {
438	      requestSettled = true;
439	      return response;
440	    });
441	    await new Promise(r => setTimeout(r, 100));
442	
443	    // Two concurrent close() calls share the same shutdown cycle
444	    const closeStart = Date.now();
445	    await Promise.all([app.close(), app.close()]);
446	    const closeElapsed = Date.now() - closeStart;
447	
