import { INestApplication } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';
import * as http from 'http';
import { AppModule } from '../src/app.module.js';
import { resetAppCounters, appCounters } from '../src/app.controller.js';

describe('PROBE', () => {
  let app: INestApplication;

  afterEach(async () => {
    if (app) await app.close();
  });

  it('sequential close twice: cleanup once', async () => {
    resetAppCounters();
    app = await NestFactory.create<NestFastifyApplication>(
      AppModule,
      new FastifyAdapter({ return503OnClosing: true }),
      { logger: false },
    );
    await app.listen(0);
    await app.close();
    await app.close();
    console.log('CLEANUP AFTER TWO SEQUENTIAL CLOSES:', appCounters.cleanupCount);
  });

  it('close with idle keep-alive socket hangs?', async () => {
    app = await NestFactory.create<NestFastifyApplication>(
      AppModule,
      new FastifyAdapter({ return503OnClosing: true }),
      { logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;

    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
    await new Promise<void>((resolve, reject) => {
      http.get(`http://localhost:${port}/slow?delay=10`, { agent }, res => {
        res.resume();
        res.on('end', resolve);
      }).on('error', reject);
    });
    // Socket now idle but kept alive in the agent
    const start = Date.now();
    const closePromise = app.close();
    const timer = new Promise<void>(resolve => setTimeout(() => resolve(), 3000));
    await Promise.race([closePromise.then(() => console.log('CLOSE RESOLVED in', Date.now() - start, 'ms')), timer.then(() => console.log('CLOSE DID NOT RESOLVE within 3s'))]);
    agent.destroy();
  });

  it('close with idle connection that never sent a request', async () => {
    app = await NestFactory.create<NestFastifyApplication>(
      AppModule,
      new FastifyAdapter({ return503OnClosing: true }),
      { logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;

    const socket = require('net').createConnection(port, '127.0.0.1');
    await new Promise<void>(resolve => socket.once('connect', resolve));
    const start = Date.now();
    const closePromise = app.close();
    const timer = new Promise<void>(resolve => setTimeout(() => resolve(), 3000));
    await Promise.race([closePromise.then(() => console.log('CLOSE RESOLVED in', Date.now() - start, 'ms')), timer.then(() => console.log('CLOSE HANGS > 3s with bare idle connection'))]);
    socket.destroy();
  });

  it('stats after close still readable', async () => {
    resetAppCounters();
    app = await NestFactory.create<NestFastifyApplication>(
      AppModule,
      new FastifyAdapter({ return503OnClosing: true }),
      { logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;
    await new Promise<void>((resolve, reject) => {
      http.get(`http://localhost:${port}/slow?delay=10`, { headers: { Connection: 'close' } }, res => {
        res.resume();
        res.on('end', resolve);
      }).on('error', reject);
    });
    await app.close();
    console.log('FINAL COUNTERS:', JSON.stringify(appCounters));
  });
});

