import {
  Body,
  Controller,
  Get,
  HttpCode,
  Post,
  Query,
} from '@nestjs/common';
import { appCounters } from './app.controller.js';

/**
 * Deterministic shutdown probe exposed at "/graceful-probe".
 *
 * GET  ?mode=slow   - simulates in-flight work ("delay" in ms, 500 by
 *                     default) and returns "ok"
 * GET  ?mode=error  - simulates in-flight work, then throws so the original
 *                     exception status/body must survive a concurrent close
 * GET  ?mode=stats  - reports the business counters without mutating them
 * POST ?mode=echo   - increments the counters only once the full request
 *                     body has been received, then echoes it back
 */
@Controller('graceful-probe')
export class GracefulProbeController {
  @Get()
  async probeGet(@Query('mode') mode: string = 'slow', @Query('delay') delay?: string) {
    if (mode === 'stats') {
      return {
        handlerEntries: appCounters.handlerEntries,
        echoCount: appCounters.echoCount,
        cleanupCount: appCounters.cleanupCount,
      };
    }

    if (mode === 'error') {
      appCounters.handlerEntries++;
      const ms = delay === undefined ? 100 : Number(delay);
      await new Promise(resolve => setTimeout(resolve, ms));
      throw new Error('boom');
    }

    // Default: slow
    appCounters.handlerEntries++;
    const ms = delay === undefined ? 500 : Number(delay);
    await new Promise(resolve => setTimeout(resolve, ms));
    return 'ok';
  }

  @Post()
  @HttpCode(201)
  probeEcho(@Body() body: unknown) {
    // Only reached once the request body has been fully received and parsed
    appCounters.handlerEntries++;
    appCounters.echoCount++;
    return body;
  }
}

